import CoreGraphics
import CoreText
import Foundation
import Testing
@testable import ThawabForGod

/// The bundled fonts register under their exact PostScript names, and the surah header and name
/// lookups generated by the pipeline (quran.sqlite `font_ligature`) resolve in them.
///
/// Ported from Mushaf's `FontAndGlyphTests`. A public clone bundles KFGQPC Hafs alone (T4), so every
/// test that needs a QUL face or the full database is guarded to `QuranTestData.hasFullData`. Not
/// guarded: `hafsAlwaysResolves` (KFGQPC Hafs is committed), `headerFitsItsSlot` (pure arithmetic)
/// and `styleNamesTheQULHeaderFonts` (names only, no font is loaded).
@MainActor
struct FontAndGlyphTests {

    @Test(.enabled(if: QuranTestData.hasFullData, QuranTestData.fullDataReason), arguments: QuranFace.allCases)
    func bundledFontRegistersAndResolves(_ face: QuranFace) {
        #expect(QuranFaces.launch.contains(face), "font \(face.postScriptName) unavailable")
        // `launch` is `registered()` after registration; checking the resolution directly keeps the
        // "resolves to itself" meaning Mushaf's `resolvesToItself` had.
        #expect(QuranFaces.registered().contains(face), "font \(face.postScriptName) substituted")
    }

    /// KFGQPC Hafs is committed in every clone, so the ayah text face must always register.
    @Test func hafsAlwaysResolves() {
        #expect(QuranFaces.launch.contains(.ayahText))
    }

    @Test(.enabled(if: QuranTestData.hasFullData, QuranTestData.fullDataReason))
    func surahLookupComesFromTheDatabase() async throws {
        let surahs = try await QuranTestData.repository(QuranTestData.fullDatabase).surahs(style: .madaniV2)
        #expect(surahs.count == 114)
        #expect(surahs.allSatisfy { $0.headerGlyph != nil && $0.nameGlyph != nil })
        #expect(Set(surahs.compactMap(\.headerGlyph)).count == 114)
        #expect(surahs.map(\.nameGlyph) == (1...114).map { String(format: "surah%03d", $0) })
        // QUL's value is "\u{FC45} " (trailing space trimmed by the pipeline).
        #expect(surahs[0].headerGlyph?.unicodeScalars.map(\.value) == [0xFC45])
    }

    /// Every header code point has a glyph in QCF_SurahHeader_COLOR, as wide as
    /// `MushafPageMetrics.headerAdvanceEm` says.
    @Test(.enabled(if: QuranTestData.hasFullData, QuranTestData.fullDataReason))
    func everyHeaderGlyphIsInTheHeaderFont() async throws {
        FontRegistrar.registerBundledFonts()
        let surahs = try await QuranTestData.repository(QuranTestData.fullDatabase).surahs(style: .madaniV2)
        let font = CTFontCreateWithName(QuranFace.surahHeader.postScriptName as CFString, 100, nil)
        for surah in surahs {
            var utf16 = Array(try #require(surah.headerGlyph).utf16)
            var glyphs = [CGGlyph](repeating: 0, count: utf16.count)
            #expect(CTFontGetGlyphsForCharacters(font, &utf16, &glyphs, utf16.count), "surah \(surah.number)")
            var advance = CGSize.zero
            CTFontGetAdvancesForGlyphs(font, .horizontal, glyphs, &advance, 1)
            #expect(abs(advance.width / 100 - MushafPageMetrics.headerAdvanceEm) < 0.01, "surah \(surah.number)")
        }
    }

    /// The header fills the width unless the slot is too low; it never overflows either.
    @Test(arguments: [CGSize(width: 347, height: 520), CGSize(width: 900, height: 700), CGSize(width: 300, height: 900)])
    func headerFitsItsSlot(_ size: CGSize) throws {
        let page = MushafPage(number: 50, juz: 3, lines: [])
        let metrics = MushafPageMetrics(page: page, measurement: PageMeasurement(lineWidths: [:]), size: size, slotCount: 15)
        let width = metrics.headerFontSize * MushafPageMetrics.headerAdvanceEm
        let height = metrics.headerFontSize * MushafPageMetrics.headerHeightEm
        #expect(width <= size.width)
        #expect(height <= metrics.slotHeight)
        #expect(width >= size.width * 0.98 || height >= metrics.slotHeight * MushafPageMetrics.headerSlotFill * 0.999)
    }

    /// Sepia and Dark draw quran-common's frame (QUL ligature "surah_header" → "header") tinted,
    /// with the surah-name-v2 name on it; Paper keeps the print-coloured header (2.8).
    @Test(.enabled(if: QuranTestData.hasFullData, QuranTestData.fullDataReason))
    func themedHeaderFrameComesFromTheDatabase() async throws {
        FontRegistrar.registerBundledFonts()
        let corpus = try await QuranTestData.repository(QuranTestData.fullDatabase).loadCorpus(style: .madaniV2)
        let frame = try #require(corpus.surahHeaderFrame)
        #expect(frame == "header")
        let font = CTFontCreateWithName(QuranFace.quranCommon.postScriptName as CFString, 100, nil)
        let line = CTLineCreateWithAttributedString(NSAttributedString(string: frame, attributes: [kCTFontAttributeName as NSAttributedString.Key: font]))
        #expect(CTLineGetGlyphCount(line) == 1)
        // CTLineGetTypographicBounds returns Double; the layout constants are CGFloat.
        let advance = CGFloat(CTLineGetTypographicBounds(line, nil, nil, nil)) / 100
        #expect(abs(advance - SurahHeaderGlyph.frameAdvanceEm) < 0.01)
    }

    /// Only Paper draws the print-coloured header; needs no font, so it runs in every clone.
    @Test func onlyPaperUsesThePrintHeader() {
        #expect(ReadingPalette(theme: .paper).usesPrintHeader)
        #expect(!ReadingPalette(theme: .sepia).usesPrintHeader)
        #expect(!ReadingPalette(theme: .dark).usesPrintHeader)
    }

    @Test func styleNamesTheQULHeaderFonts() {
        #expect(MushafStyle.madaniV2.headerFont == .surahHeader)
        #expect(MushafStyle.madaniV2.surahNameFont == .surahName)
        #expect(QuranFace.surahHeader.postScriptName == "QCF_SurahHeader_COLOR")
    }
}
